    "form-data": "^4.0.1",
    "mime-types": "^2.1.35"
  },
  "devDependencies": {
    "@types/mime-types": "^2.1.4",
    "@types/node": "^22.10.7",
    "typescript": "^5.7.3"
  },
  "bugs": {
    "url": "https://github.com/tokenrip/tokenrip/issues"
