  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.wshobson/maverick-mcp",
  "description": "Stock analysis MCP server with market data, technical indicators, and AI research tools.",
  "status": "active",
  "repository": {
    "url": "https://github.com/wshobson/maverick-mcp",
    "source": "github"
  },
  "version": "1.1.0",
  "packages": [
    {
      "registryType": "pypi",
      "registryBaseUrl": "https://pypi.org",
      "identifier": "maverick-mcp-server",
      "version": "1.1.0",
      "runtimeHint": "uvx",
      "transport": {
        "type": "stdio"
      },
      "environmentVariables": [
        {
          "name": "DATABASE_URL",
          "description": "Optional database URL. Defaults to SQLite (sqlite:///maverick.db) if not provided. PostgreSQL supported for better performance.",
          "isRequired": false,
          "isSecret": false
        },
        {
          "name": "REDIS_HOST",
          "description": "Optional Redis host for enhanced caching performance. Defaults to in-memory caching if not provided.",
          "isRequired": false,
          "isSecret": false
        },
        {
          "name": "REDIS_PORT",
          "description": "Optional Redis port (default: 6379)",
          "isRequired": false,
          "isSecret": false
        },
        {
          "name": "LLM_PROVIDER",
          "description": "Optional LLM provider for the research extra (e.g. anthropic, openai, openai_compatible). Required only to enable research agent tools; bring your own API key.",
          "isRequired": false,
          "isSecret": false
        },
        {
          "name": "LLM_API_KEY",
          "description": "Optional API key for the configured LLM_PROVIDER. Required only when LLM_PROVIDER is set.",
          "isRequired": false,
          "isSecret": true
        },
        {
          "name": "LLM_MODEL",
          "description": "Optional model name for the configured LLM_PROVIDER. Required only when LLM_PROVIDER is set.",
          "isRequired": false,
          "isSecret": false
        },
        {
          "name": "LLM_BASE_URL",
          "description": "Optional base URL override, required when LLM_PROVIDER=openai_compatible.",
          "isRequired": false,
          "isSecret": false
        },
        {
          "name": "LLM_TEMPERATURE",
          "description": "Optional sampling temperature for the configured LLM_PROVIDER. Defaults to 0.0.",
          "isRequired": false,
          "isSecret": false
        },
        {
          "name": "EXA_API_KEY",
          "description": "Optional API key for Exa web search (research extra). Get at https://exa.ai",
          "isRequired": false,
          "isSecret": true
        },
        {
          "name": "RESEARCH_SEARCH_BACKEND",
          "description": "Optional research search backend: exa (default) or searxng.",
          "isRequired": false,
          "isSecret": false
        },
        {
          "name": "SEARXNG_BASE_URL",
          "description": "Optional base URL of a self-hosted SearXNG instance with the JSON format enabled; used when RESEARCH_SEARCH_BACKEND=searxng.",
          "isRequired": false,
          "isSecret": false
        }
      ]
    },
    {
      "registryType": "oci",
      "identifier": "ghcr.io/wshobson/maverick-mcp:1.1.0",
